const tz = 'Asia/Shanghai';
function pad(n){return n<10?('0'+n):(''+n)}
// 以上海时区计算“今天”
const nowTz = new Date(new Date().toLocaleString('en-US', { timeZone: tz }));
const y = nowTz.getFullYear();
const m = pad(nowTz.getMonth()+1);
const d = pad(nowTz.getDate());
const startMs = Date.parse(`${y}-${m}-${d}T00:00:00+08:00`);
const endMs   = startMs + 24*60*60*1000; // [start, end)
return $input.all().map(item => {
  const {libraryId, data} = item.json.item
  // 读取全局静态数据里的 lastVideoId（若首次则为 null）
const lastId = data.lastVideoId ?? null;

// 构造 SQL（示例：表名 assets；若你的实际表名不同，请改这里）
let sql = `SELECT id,name,created_at,folder_id,custom_fields FROM files WHERE created_at >= ${startMs} AND created_at < ${endMs}`;
if (lastId) sql += ` AND id > ${lastId}`;
sql += ' ORDER BY id ASC;';

return  {json: { startMs, endMs, lastId, libraryId, libraryData: data, sql, dateStr: `${y}-${m}-${d}` }};
});

// 输入：Mira: Query Today Videos 的返回 { success: true, data: [...] }
const json_data = $('Read File').item.json.content;
return $input.all().map(item => {
const rows = Array.isArray(item.json.data) ? item.json.data : [];
const agg = {};                // key: folderKey（数字ID或"__UNCLASSIFIED__"） => { count, uploaders: {name:cnt} }
const folderIdSet = new Set(); // 仅收集有效的数字 folder_id
let maxId = null;

function parseUploader(cf) {
  try {
    if (!cf) return '未知';
    const obj = typeof cf === 'string' ? JSON.parse(cf) : cf;
    return obj && obj.uploader ? String(obj.uploader) : '未知';
  } catch {
    return '未知';
  }
}

for (const v of rows) {
  const fidRaw = v.folder_id;
  const hasNumericFolder = Number.isFinite(Number(fidRaw)) && fidRaw !== null;

  const folderKey = hasNumericFolder ? String(Number(fidRaw)) : '__UNCLASSIFIED__';
  if (!agg[folderKey]) agg[folderKey] = { count: 0, uploaders: {} };

  agg[folderKey].count += 1;

  const uploader = parseUploader(v.custom_fields);
  agg[folderKey].uploaders[uploader] = (agg[folderKey].uploaders[uploader] || 0) + 1;

  if (typeof v.id === 'number') {
    maxId = (maxId === null ? v.id : Math.max(maxId, v.id));
    json_data[$('Init Today + lastId').item.json.libraryId].lastVideoId = maxId;
  }

  // 仅当是有效的数字 folder_id 时，加入 folderIds
  if (hasNumericFolder) folderIdSet.add(Number(fidRaw));
}

// 输出
return {item: {
  libraryId: $('Init Today + lastId').first().json.libraryId,
  total: rows.length,
  agg,                                // 带有 "__UNCLASSIFIED__" 的分组
  folderIds: Array.from(folderIdSet), // 不含 null/无效
  maxId,
  json_data
}};

});

