// 读取两个上游：聚合结果 + 文件夹标题
const aggItem  = $('Aggregate by folder_id').first().json.item
const folderRes =$input.first().json

const total = Number(aggItem.total || 0);
const agg   = aggItem.agg || {};

// id => title
const titleMap = new Map();
try {
  const list = Array.isArray(folderRes.data) ? folderRes.data : [];
  for (const f of list) {
    titleMap.set(Number(f.id), f.title || `Folder ${f.id}`);
  }
} catch {}

// 日期（上海时区）
const tz = 'Asia/Shanghai';
const nowTz = new Date(new Date().toLocaleString('en-US', { timeZone: tz }));
const y = nowTz.getFullYear();
const m = String(nowTz.getMonth() + 1).padStart(2, '0');
const d = String(nowTz.getDate()).padStart(2, '0');
const dateStr = `${y}-${m}-${d}`;

// 上传者渲染（带计数）
function renderUploaders(uploaders = {}) {
  const pairs = Object.entries(uploaders);
  if (!pairs.length) return '`匿名`';
  return pairs
    .map(([u, c]) => (c > 1 ? `\`${u}×${c}\`` : `\`${u}\``))
    .join('、');
}

// 行渲染
function renderLine(folderKey, info) {
  const isUnclassified = folderKey === '__UNCLASSIFIED__';
  const folderTitle = isUnclassified
    ? '未分类'
    : (titleMap.get(Number(folderKey)) || `文件夹 ${folderKey}`);

  return `- **${info.count}** × **${folderTitle}**  · 上传者：${renderUploaders(info.uploaders)}`;
}

// 分组排序：按数量降序；同数时“有标题”优先，“未分类”最后
const sortedEntries = Object.entries(agg).sort(([ka, ia], [kb, ib]) => {
  if (ia.count !== ib.count) return ib.count - ia.count;
  if (ka === '__UNCLASSIFIED__') return 1;
  if (kb === '__UNCLASSIFIED__') return -1;
  return 0;
});

// 构造 Markdown
let mdTitle = `🎬 素材上新播报 · ${dateStr}`;
let mdText = '';

if (total === 0) {
  // 无新增：如需“空时不发”，可让下游根据 send=false 判断
  mdText = [
    `> 🗓️ **${dateStr}**`,
    '',
    '今天没有新的视频素材上新～ (￣▽￣)ﾉ',
  ].join('\n');
} else {
  const folderCount = sortedEntries.length;
  const lines = sortedEntries.map(([k, info]) => renderLine(k, info));

  mdText = [
    `> 🗓️ **${dateStr}**`,
    '',
    `**【${$('Init Today + lastId').first().json.libraryData.title}】总览**`,
    `- 新增视频素材：**${total}**`,
    `- 涉及文件夹：**${folderCount}**`,
    '',
    `**分组明细**`,
    ...lines,
    '',
    '✨ 去看看吧~'
  ].join('\n');
}

// 返回 markdown + 兼容旧 text 字段
return [{
  md: { title: mdTitle, text: mdText },
  message: mdText,    // 兼容：如果你还在用 text 类型
  send: total > 0     // 下游可用来判断是否发送
}];
